export const CreateObjectView = observer(({ model }: { model: CreateObjectModel }) => {
  return (
    <div id="CreateObjectView">
      <label htmlFor="selectedAssetId">Asset:</label>
      <select id="selectedAssetId" value={model.selectedAsset} onChange={(e) => {
        if (e.target.value) {
          model.createObject(e.target.value).then();
          model.setSelectedAsset(e.target.value);
