 Here's a C++ program that meets your requirements:

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <stdexcept>

using namespace std;

void fibonacci(int n, int a, int b, vector<int>& sequence) {
    if (n <= 0) {
        throw invalid_argument("Number of sequence elements must be positive.");
    }

    if (!isdigit(a + '0') || !isdigit(b + '0')) {
        throw invalid_argument("First two integers must be digits.");
    }

    sequence.push_back(a);
    sequence.push_back(b);

    if (n > 2) {
        fibonacci(n - 1, b, a + b, sequence);
    }
}

int main() {
    int num_elements, first, second;

    cout << "Enter the first two integers of the Fibonacci sequence: ";
    cin >> first >> second;

    cout << "Enter the number of sequence elements to generate: ";
    cin >> num_elements;

    try {
        vector<int> sequence;
        fibonacci(num_elements, first, second, sequence);

        cout << "Fibonacci sequence (" << num_elements << " elements):";
        for (const auto& elem : sequence) {
            cout << elem << ", ";
        }
        cout << endl;
    } catch (invalid_argument& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
```

This program uses a recursive `fibonacci` function that generates the Fibonacci sequence up to a given number of elements, using the first two sequence elements as arguments. It prompts the user for the first two integers and the number of sequence elements to generate, and performs error checking for invalid inputs. If an error is detected, it prints an error message and terminates the program with a non-zero exit code. Otherwise, it generates and outputs the sequence.

